package com.buzbuz.smartautoclicker.core.script.runtime.api

import com.buzbuz.smartautoclicker.core.script.runtime.session.SessionAutomationHost
import com.buzbuz.smartautoclicker.core.script.runtime.ScriptApiException
import kotlinx.coroutines.currentCoroutineContext
import kotlinx.coroutines.delay
import kotlinx.coroutines.ensureActive
import kotlinx.coroutines.yield
import kotlinx.coroutines.CancellationException
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.booleanOrNull
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.intOrNull
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import kotlinx.serialization.json.longOrNull
import kotlinx.serialization.json.put

/** API v1 transport. Instances belong to one session and are called through its serialized gate. */
class ScreenAutomationHost(
    private val backend: ScreenAutomationBackend,
    private val resumeCheck: suspend (ScreenAutomationBackend) -> Boolean,
    private val monotonicNanos: () -> Long = System::nanoTime,
    private val startParameters: JsonObject = JsonObject(emptyMap()),
    private val onDiagnostic: (ScriptDiagnostic) -> Unit = {},
    initialResumeQuery: JsonObject? = null,
    private val referenceProfile: ScreenProfile? = null,
    private val detailedDiagnostics: () -> Boolean = { false },
) : SessionAutomationHost {
    private var sequence = 0L
    private var frame: Long? = null
    private var size: ScreenSize? = null
    private var stage: String? = null
    private var resumeQuery = initialResumeQuery
    private var pausedAt: Long? = null
    private var pausedNanos = 0L
    private var resumeGeneration = 0L

    override suspend fun call(requestJson: String): String {
        currentCoroutineContext().ensureActive()
        require(requestJson.length <= 262144) { "request.length=${requestJson.length}; expected at most 262144 characters" }
        val request = Json.parseToJsonElement(requestJson).jsonObject
        require(request.int("apiVersion") == 1) { "apiVersion=${request["apiVersion"]}; expected 1" }
        val operation = request.string("operation")
        if (!detailedDiagnostics()) return perform(operation, request).toString()
        val startedAt = monotonicNanos()
        var response: JsonObject? = null
        var outcome = "success"
        try {
            response = perform(operation, request)
            return response.toString()
        } catch (failure: Throwable) {
            outcome = when (failure) {
                is ScriptStopRequested -> "stopped"
                is CancellationException -> "cancelled"
                is ScriptApiException -> failure.code
                else -> "failed"
            }
            throw failure
        } finally {
            val completedAt = monotonicNanos()
            onDiagnostic(ScriptDiagnostic("operation", stage, operation, completedAt,
                operation, completedAt - startedAt, outcome, operationDetails(operation, request, response)))
        }
    }

    private suspend fun perform(operation: String, request: JsonObject): JsonObject {
        val response = when (operation) {
            "observe" -> observe()
            "read" -> read(request)
            "readAll" -> readAll(request)
            "profile" -> {
                requireFrame(request)
                val profile = checkNotNull(referenceProfile) { "screen: no calibrated reference profile in this package" }
                profile.resolve(checkNotNull(size))
            }
            "tap" -> {
                if (request.containsKey("frame")) requireFrame(request)
                backend.tap(point(request), request.duration())
                invalidateObservations()
                success()
            }
            "tapSequence" -> {
                requireFrame(request)
                backend.tapSequence(tapSequence(request))
                invalidateObservations()
                success()
            }
            "swipe" -> {
                if (request.containsKey("frame")) requireFrame(request)
                backend.swipe(point(request.getValue("from").jsonObject), point(request.getValue("to").jsonObject), request.duration())
                invalidateObservations()
                success()
            }
            "sleep" -> { delay(request.duration()); success() }
            "zoom" -> {
                if (request.containsKey("frame")) requireFrame(request)
                val directionName = request.string("direction")
                val direction = ScreenZoomDirection.entries.find { it.name.lowercase() == directionName }
                    ?: throw IllegalArgumentException("direction=$directionName; expected in or out")
                val intensity = request.int("intensityPx")
                require(intensity in 1..10000) { "intensityPx=$intensity; expected 1..10000 pixels" }
                backend.zoom(point(request.getValue("center").jsonObject), intensity, request.duration(), direction)
                invalidateObservations()
                success()
            }
            "gesture" -> {
                if (request.containsKey("frame")) requireFrame(request)
                backend.gesture(gesture(request))
                invalidateObservations()
                success()
            }
            "now" -> buildJsonObject {
                put("activeNanos", (pausedAt ?: monotonicNanos()) - pausedNanos)
                frame?.let { put("frame", it) }
            }
            "parameters" -> buildJsonObject { put("values", startParameters) }
            "resumeWhen" -> {
                resumeQuery = request["query"] as? JsonObject
                    ?: throw IllegalArgumentException("resumeWhen.query: expected a recognition query object")
                success()
            }
            "stop" -> {
                val reason = request.string("message")
                require(reason.isNotBlank() && reason.length <= 4096) { "stop.message: expected 1..4096 nonblank characters" }
                onDiagnostic(ScriptDiagnostic("stop", stage, reason, monotonicNanos()))
                throw ScriptStopRequested(reason)
            }
            "stage", "log" -> {
                val message = request.string("message")
                require(message.length <= 4096) { "message.length=${message.length}; expected at most 4096 characters" }
                if (operation == "stage") {
                    val name = request.string("name")
                    require(name.isNotBlank() && name.length <= 128) { "stage.name=$name; expected 1..128 nonblank characters" }
                    stage = name
                }
                onDiagnostic(ScriptDiagnostic(operation, stage, message, monotonicNanos()))
                success()
            }
            else -> throw IllegalArgumentException("operation=$operation; expected a supported API v1 operation")
        }
        currentCoroutineContext().ensureActive()
        return response
    }

    override suspend fun releasePointers() = backend.releasePointers()

    override suspend fun pauseOperationClock() {
        if (pausedAt == null) {
            pausedAt = monotonicNanos()
            resumeGeneration++
        }
    }

    override suspend fun resumeOperationClock() {
        pausedAt?.let { pausedNanos += monotonicNanos() - it }
        pausedAt = null
    }

    override suspend fun invalidateObservations() {
        frame = null
        size = null
        backend.invalidateObservation()
    }

    override suspend fun revalidate(): Boolean {
        val query = resumeQuery ?: return resumeCheck(backend)
        return try {
            val observation = observe()
            val response = read(JsonObject(query + ("frame" to observation.getValue("frame"))))
            response["status"]?.jsonPrimitive?.content == "found"
        } finally {
            invalidateObservations()
        }
    }

    private suspend fun observe(): JsonObject {
        invalidateObservations()
        val captured = backend.capture()
        check(captured.width > 0 && captured.height > 0) { "Capture returned invalid screen dimensions: $captured" }
        size = captured
        frame = ++sequence
        return buildJsonObject {
            put("status", "success")
            put("frame", sequence)
            put("resumeGeneration", resumeGeneration)
            put("monotonicNanos", monotonicNanos())
            put("width", captured.width)
            put("height", captured.height)
        }
    }

    private suspend fun read(request: JsonObject): JsonObject {
        requireFrame(request)
        return recognize(recognitionQuery(request))
    }

    private suspend fun readAll(request: JsonObject): JsonObject {
        requireFrame(request)
        val values = request["queries"] as? JsonArray
        require(values != null && values.size in 1..64) { "readAll.queries: expected 1..64 recognition queries" }
        // Validate the complete group before starting native work. One API checkpoint owns the whole frame.
        val queries = values.mapIndexed { index, value ->
            val query = value as? JsonObject
                ?: throw IllegalArgumentException("readAll.queries[$index]=$value; expected a recognition query object")
            recognitionQuery(query)
        }
        val results = queries.map { query ->
            yield()
            recognize(query)
        }
        return buildJsonObject { put("results", JsonArray(results)) }
    }

    private fun recognitionQuery(request: JsonObject): RecognitionQuery {
        val kindName = request.string("kind")
        val kind = RecognitionKind.entries.find { it.name.lowercase() == kindName }
            ?: throw IllegalArgumentException("kind=$kindName; expected image, text, number or color")
        val area = request.getValue("region").jsonObject
        val region = ScreenRegion(area.int("left"), area.int("top"), area.int("right"), area.int("bottom"))
        val currentSize = checkNotNull(size)
        require(region.left >= 0 && region.top >= 0 && region.right > region.left && region.bottom > region.top &&
            region.right <= currentSize.width && region.bottom <= currentSize.height) {
            "region=$region; expected a nonempty region within $currentSize"
        }
        val threshold = request.int("threshold")
        require(threshold in 0..100) { "threshold=$threshold; expected 0..100" }
        val reference = request["reference"]?.jsonPrimitive?.content
        if (kind != RecognitionKind.NUMBER) require(!reference.isNullOrBlank()) {
            "reference: expected a nonempty named resource for $kindName"
        }
        return RecognitionQuery(kind, region, threshold, reference)
    }

    private suspend fun recognize(query: RecognitionQuery): JsonObject {
        val result = backend.recognize(query)
        val status = if (query.kind == RecognitionKind.NUMBER && result.status == RecognitionStatus.FOUND &&
            (result.number == null || !result.number.isFinite())) RecognitionStatus.INVALID_READING else result.status
        return buildJsonObject {
            put("frame", checkNotNull(frame))
            put("status", status.name.lowercase())
            if (result.confidence.isFinite()) put("confidence", result.confidence)
            if (status == RecognitionStatus.FOUND) {
                result.position?.let { put("x", it.x); put("y", it.y) }
                result.size?.let { put("width", it.width); put("height", it.height) }
                result.number?.let { if (it.isFinite()) put("number", it) }
            }
        }
    }

    private fun requireFrame(request: JsonObject) {
        val requested = (request["frame"] as? JsonPrimitive)?.takeUnless { it.isString }?.longOrNull
        require(requested != null) { "frame=${request["frame"]}; expected an observation frame integer" }
        if (frame == null || requested != frame) throw ScriptApiException("stale_observation",
            "frame=$requested; expected the current frame $frame; observe again")
    }

    private fun point(request: JsonObject): ScreenPoint {
        val point = ScreenPoint(request.int("x"), request.int("y"))
        require(point.x >= 0 && point.y >= 0) { "position=$point; expected nonnegative screen coordinates" }
        return point
    }

    private fun success() = buildJsonObject { put("status", "success") }
    private fun tapSequence(request: JsonObject): List<ScreenTapStep> {
        val values = request["steps"] as? JsonArray
        require(values != null && values.size in 1..64) { "steps: expected 1..64 taps totalling at most 1000 milliseconds" }
        val steps = values.mapIndexed { index, value ->
            val step = value as? JsonObject ?: throw IllegalArgumentException("steps[$index]=$value; expected a tap object")
            val at = step["at"] as? JsonObject ?: throw IllegalArgumentException("steps[$index].at=${step["at"]}; expected x/y coordinates")
            val press = step.int("pressMs").toLong()
            val after = step.int("afterMs").toLong()
            require(press in 1..1000 && after in 0..1000) {
                "steps[$index].pressMs=$press, afterMs=$after; expected press 1..1000 and after 0..1000 milliseconds"
            }
            val position = point(at)
            val bounds = checkNotNull(size)
            require(position.x < bounds.width && position.y < bounds.height) {
                "steps[$index].at=$position; expected coordinates inside $bounds"
            }
            ScreenTapStep(position, press, after)
        }
        val total = steps.sumOf { it.pressMs + it.afterMs }
        require(total <= 1000) { "steps.durationMs=$total; expected at most 1000 milliseconds per cooperative block" }
        return steps
    }
    private fun gesture(request: JsonObject): List<ScreenGestureFinger> {
        val fingers = request["fingers"] as? JsonArray
        require(fingers != null && fingers.size in 1..10) { "fingers: expected 1..10 gesture fingers" }
        return fingers.mapIndexed { index, value ->
            val finger = value as? JsonObject ?: throw IllegalArgumentException("fingers[$index]: expected an object")
            fun duration(field: String): Long {
                if (!finger.containsKey(field)) return 0L
                val amount = (finger[field] as? JsonPrimitive)?.takeUnless { it.isString }?.longOrNull
                    ?: throw IllegalArgumentException("fingers[$index].$field=${finger[field]}; expected integer milliseconds")
                require(amount in 0..60000) { "fingers[$index].$field=$amount; expected 0..60000 milliseconds" }
                return amount
            }
            val hold = if (!finger.containsKey("keepDown")) false else
                (finger["keepDown"] as? JsonPrimitive)?.takeUnless { it.isString }?.booleanOrNull
                    ?: throw IllegalArgumentException("fingers[$index].keepDown=${finger["keepDown"]}; expected a boolean")
            require(!hold || index == 0) { "fingers[$index].keepDown=true; only the first finger can remain held" }
            val stepValues = if (!finger.containsKey("steps")) JsonArray(emptyList()) else finger["steps"] as? JsonArray
                ?: throw IllegalArgumentException("fingers[$index].steps: expected an array")
            val steps = stepValues.also {
                require(it.size <= 64) { "fingers[$index].steps.size=${it.size}; expected at most 64" }
            }.map { stepValue ->
                val step = stepValue as? JsonObject ?: throw IllegalArgumentException("fingers[$index].steps: expected objects")
                ScreenGestureStep(step["to"]?.jsonObject?.let(::point), step.duration())
            }
            val startDelay = duration("startDelayMs")
            val initialHold = duration("holdMs")
            val total = startDelay + (if (initialHold == 0L && steps.isEmpty()) 50L else initialHold) + steps.sumOf { it.durationMs }
            require(total <= 60000) { "fingers[$index].durationMs=$total; expected at most 60000 milliseconds" }
            ScreenGestureFinger(point(finger.getValue("start").jsonObject), startDelay, initialHold, steps, hold)
        }
    }
    private fun JsonObject.string(field: String): String = (get(field) as? JsonPrimitive)
        ?.takeIf { it.isString }?.content ?: throw IllegalArgumentException("$field: expected a string")
    private fun JsonObject.int(field: String): Int = (get(field) as? JsonPrimitive)?.takeUnless { it.isString }?.intOrNull
        ?: throw IllegalArgumentException("$field=${get(field)}; expected an integer")
    private fun JsonObject.duration(): Long {
        val duration = (get("durationMs") as? JsonPrimitive)?.takeUnless { it.isString }?.longOrNull
        require(duration != null && duration in 1..60000) { "durationMs=$duration; expected 1..60000 milliseconds" }
        return duration
    }
}

package com.buzbuz.smartautoclicker.core.script.runtime.api

import java.util.ArrayDeque
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow

/** Bounded in-memory diagnostics; normal execution only publishes the latest event to the UI. */
class ScriptDiagnostics(private val capacity: Int = 200) {
    private val events = ArrayDeque<ScriptDiagnostic>()
    private val mutableLatest = MutableStateFlow<ScriptDiagnostic?>(null)
    val latest = mutableLatest.asStateFlow()
    private val mutableRevision = MutableStateFlow(0L)
    val revision = mutableRevision.asStateFlow()
    @Volatile var isDetailedEnabled: Boolean = false
        private set

    init { require(capacity in 1..1000) { "capacity=$capacity; expected 1..1000 events" } }

    /** Enables operation timings only when requested, e.g. `diagnostics.setDetailed(viewerVisible)`. */
    fun setDetailed(enabled: Boolean) { isDetailedEnabled = enabled }

    /** Records one structured event, e.g. `host = ScreenAutomationHost(..., onDiagnostic = diagnostics::record)`. */
    @Synchronized
    fun record(event: ScriptDiagnostic) {
        if (events.size == capacity) events.removeFirst()
        events.addLast(event)
        // Operation traces belong in the detailed viewer; they must not replace the current stage/wait message.
        if (event.kind != "operation") mutableLatest.value = event
        mutableRevision.value += 1
    }

    /** Returns a stable snapshot for the diagnostic viewer. */
    @Synchronized
    fun snapshot(): List<ScriptDiagnostic> = events.toList()

    /** Exports retained events as JSON Lines, e.g. `report.writeText(diagnostics.jsonLines())`. */
    @Synchronized
    fun jsonLines(): String = events.joinToString("\n") { it.toJson() }
}

package com.buzbuz.smartautoclicker.core.script.runtime.api

import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.put

/** Structured event for bounded session logs and the execution overlay. */
data class ScriptDiagnostic(
    val kind: String,
    val stage: String?,
    val message: String,
    val monotonicNanos: Long,
    val operation: String? = null,
    val durationNanos: Long? = null,
    val outcome: String? = null,
    val details: JsonObject? = null,
) {
    /** Encodes an event for a JSON log sink, e.g. `logger.write(event.toJson())`. */
    fun toJson(): String = buildJsonObject {
        put("kind", kind)
        stage?.let { put("stage", it) }
        put("message", message)
        put("monotonicNanos", monotonicNanos)
        operation?.let { put("operation", it) }
        durationNanos?.let { put("durationNanos", it) }
        outcome?.let { put("outcome", it) }
        details?.let { put("details", it) }
    }.toString()
}

package com.buzbuz.smartautoclicker.core.script.runtime.api

import kotlinx.serialization.json.*

/** Projects bounded diagnostic metadata; never retains code, captured pixels or parameter answers. */
internal fun operationDetails(operation: String, request: JsonObject, response: JsonObject?): JsonObject = buildJsonObject {
    fun JsonObjectBuilder.primitive(name: String, source: JsonObject) {
        val value = source[name] as? JsonPrimitive ?: return
        put(name, if (value.content.length > 128) JsonPrimitive(value.content.take(128)) else value)
    }
    for (field in listOf("frame", "kind", "reference", "durationMs", "x", "y")) primitive(field, request)
    (request["region"] as? JsonObject)?.let { region ->
        put("region", buildJsonObject { for (field in listOf("left", "top", "right", "bottom")) this.primitive(field, region) })
    }
    if (operation == "parameters") {
        put("parameterCount", (response?.get("values") as? JsonObject)?.size ?: 0)
        return@buildJsonObject
    }
    if (operation == "profile") {
        response?.let {
            primitive("width", it); primitive("height", it)
            put("regions", (it["regions"] as? JsonObject)?.size ?: 0)
            put("positions", (it["positions"] as? JsonObject)?.size ?: 0)
        }
        return@buildJsonObject
    }
    if (operation == "tapSequence") put("steps", (request["steps"] as? JsonArray)?.size ?: 0)
    if (operation == "gesture") put("fingers", (request["fingers"] as? JsonArray)?.size ?: 0)
    response?.let {
        for (field in listOf("frame", "status", "number", "confidence", "x", "y", "width", "height", "resumeGeneration")) primitive(field, it)
    }
    val results = response?.get("results") as? JsonArray ?: return@buildJsonObject
    put("reads", results.size)
    for (status in listOf("found", "not_found", "invalid_reading")) {
        put(status, results.count { (it as? JsonObject)?.get("status")?.jsonPrimitive?.content == status })
    }
    val queries = request["queries"] as? JsonArray
    put("numbers", JsonArray(results.mapIndexedNotNull { index, value ->
        val result = value as? JsonObject ?: return@mapIndexedNotNull null
        val number = result["number"] as? JsonPrimitive ?: return@mapIndexedNotNull null
        buildJsonObject {
            put("index", index); put("number", number)
            ((queries?.getOrNull(index) as? JsonObject)?.get("reference") as? JsonPrimitive)?.let {
                put("reference", it.content.take(128))
            }
        }
    }.take(8)))
}

package com.buzbuz.smartautoclicker.core.script.runtime

import com.dokar.quickjs.ModuleContent
import com.dokar.quickjs.QuickJs
import com.dokar.quickjs.QuickJsException
import com.dokar.quickjs.binding.asyncFunction
import com.dokar.quickjs.moduleLoader
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.async
import kotlinx.coroutines.cancelAndJoin
import kotlinx.coroutines.coroutineScope
import kotlinx.coroutines.delay
import kotlinx.coroutines.isActive
import kotlinx.coroutines.launch
import kotlinx.coroutines.withTimeoutOrNull
import kotlinx.coroutines.withContext
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.put

/** A fresh interpreter per operation prevents globals and callbacks leaking into later sessions. */
class QuickJsScriptRuntime(
    private val dispatcher: CoroutineDispatcher,
    private val limits: ScriptRuntimeLimits = ScriptRuntimeLimits(),
) : ScriptRuntime {
    init {
        require(limits.memoryBytes > 0) { "memoryBytes=${limits.memoryBytes}; expected a positive byte count" }
        require(limits.stackBytes > 0) { "stackBytes=${limits.stackBytes}; expected a positive byte count" }
        require(limits.busyTimeoutMs > 0) { "busyTimeoutMs=${limits.busyTimeoutMs}; expected positive milliseconds" }
    }

    override suspend fun validate(program: ScriptProgram) = withInterpreter(program) { runtime, snapshot ->
        snapshot.sources.forEach { (name, code) -> runtime.compile(code, filename = name, asModule = true) }
    }

    override suspend fun execute(program: ScriptProgram, host: ScriptHost) = withInterpreter(program) { runtime, snapshot ->
        runtime.asyncFunction("__klickrCall") { arguments ->
            require(arguments.size == 1 && arguments[0] is String) {
                "API request: expected one JSON string"
            }
            try {
                host.call(arguments[0] as String)
            } catch (expected: ScriptApiException) {
                buildJsonObject {
                    put("status", "error")
                    put("code", expected.code)
                    put("message", expected.message)
                }.toString()
            }
        }
        runtime.evaluate<Unit>(snapshot.sources.getValue(snapshot.entry), filename = snapshot.entry, asModule = true)
    }

    private suspend fun withInterpreter(
        program: ScriptProgram,
        operation: suspend (QuickJs, ScriptProgram) -> Unit,
    ) = withContext(dispatcher) {
        val snapshot = program.copy(sources = program.sources.toMap())
        require("klickr" !in snapshot.sources) { "sources[klickr]: reserved for the versioned automation API" }
        require(snapshot.entry in snapshot.sources) {
            "entry=${snapshot.entry}; expected an existing source file"
        }
        val loader = moduleLoader {
            load { name ->
                val source = if (name == "klickr") ScriptApiV1.source else snapshot.sources[name]
                source?.let(ModuleContent::Source)
            }
        }
        val runtime = QuickJs.create(dispatcher, loader)
        try {
            runtime.memoryLimit = limits.memoryBytes
            runtime.maxStackSize = limits.stackBytes
            // The binding's evaluation deadline includes time awaited in host calls (v1.0.18).
            // Probe its native lock instead: an awaiting runtime responds, busy JS cannot.
            runtime.evaluationTimeoutMillis = 0
            withBusyBudget(runtime) { operation(runtime, snapshot) }
        } catch (error: QuickJsException) {
            throw ScriptExecutionException(
                error.message ?: "JavaScript execution failed", error.fileName, error.lineNumber,
                error.columnNumber, error.stack, error,
            )
        } finally {
            runtime.close()
        }
    }

    @OptIn(com.dokar.quickjs.ExperimentalQuickJsApi::class)
    private suspend fun withBusyBudget(runtime: QuickJs, operation: suspend () -> Unit) = coroutineScope {
        val watchdog = launch(Dispatchers.Default) {
            while (isActive) {
                val probe = async(Dispatchers.IO) { runtime.withNativeContext { } }
                if (withTimeoutOrNull(limits.busyTimeoutMs) { probe.await(); true } == null) {
                    runtime.interruptEvaluation()
                    probe.join()
                    break
                }
                delay(minOf(50, limits.busyTimeoutMs))
            }
        }
        try {
            operation()
        } finally {
            // Native probes must finish before the interpreter is closed.
            watchdog.cancelAndJoin()
        }
    }
}

package com.buzbuz.smartautoclicker.core.script.runtime.session

import com.buzbuz.smartautoclicker.core.script.runtime.ScriptHost
import com.buzbuz.smartautoclicker.core.script.runtime.ScriptProgram
import com.buzbuz.smartautoclicker.core.script.runtime.ScriptRuntime
import com.buzbuz.smartautoclicker.core.script.runtime.api.ScriptStopRequested
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.Job
import kotlinx.coroutines.NonCancellable
import kotlinx.coroutines.currentCoroutineContext
import kotlinx.coroutines.ensureActive
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.job
import kotlinx.coroutines.withContext

enum class ScriptSessionState {
    PREPARING, RUNNING, PAUSING, PAUSED, REVALIDATING, STOPPING, STOPPED, COMPLETED, FAILED,
}

data class ScriptSessionStatus(val state: ScriptSessionState, val failure: Throwable? = null, val reason: String? = null)

interface SessionAutomationHost : ScriptHost {
    /** Suspends operation deadlines while paused; session/diagnostic clocks keep advancing. */
    suspend fun pauseOperationClock() {}
    /** Restarts operation deadlines after a successful screen revalidation. */
    suspend fun resumeOperationClock() {}
    /** Releases held pointers at a cooperative pause, e.g. before showing a paused overlay. */
    suspend fun releasePointers()
    /** Invalidates previous frame/results, e.g. when entering a paused state. */
    suspend fun invalidateObservations()
    /** Checks the script's declared resume condition against a new observation. */
    suspend fun revalidate(): Boolean
}

/** A single-use execution preserving the JS stack only at supported host API checkpoints. */
class ScriptSession(
    private val runtime: ScriptRuntime,
    private val coordinator: AutomationSessionCoordinator,
) {
    private val control = Any()
    private val mutableStatus = MutableStateFlow(ScriptSessionStatus(ScriptSessionState.PREPARING))
    val status: StateFlow<ScriptSessionStatus> = mutableStatus.asStateFlow()
    private var execution: Job? = null
    private var started = false
    @Volatile private var stopReason: String? = null

    /** Runs a fixed source snapshot. Example: `scope.launch { session.run(program, host) }`. */
    suspend fun run(program: ScriptProgram, host: SessionAutomationHost) {
        val snapshot = program.copy(sources = program.sources.toMap())
        val job = currentCoroutineContext().job
        synchronized(control) {
            check(!started) { "A ScriptSession can only run once" }
            started = true
            execution = job
        }
        try {
            coordinator.withSession { access ->
                try {
                    runtime.validate(snapshot)
                    currentCoroutineContext().ensureActive()
                    transition(ScriptSessionState.PREPARING, ScriptSessionState.RUNNING)
                    runtime.execute(snapshot) { request ->
                        access.perform {
                            checkpoint(host)
                            currentCoroutineContext().ensureActive()
                            try {
                                host.call(request)
                            } catch (requested: ScriptStopRequested) {
                                stop(requested.reason)
                                throw CancellationException(requested.reason, requested)
                            }
                        }
                    }
                } finally {
                    withContext(NonCancellable) {
                        access.perform {
                            host.releasePointers()
                            host.invalidateObservations()
                        }
                    }
                }
            }
            currentCoroutineContext().ensureActive()
            synchronized(control) {
                val stopped = mutableStatus.value.state == ScriptSessionState.STOPPING
                mutableStatus.value = ScriptSessionStatus(
                    if (stopped) ScriptSessionState.STOPPED else ScriptSessionState.COMPLETED,
                    reason = if (stopped) stopReason else null,
                )
            }
        } catch (cancelled: CancellationException) {
            mutableStatus.value = ScriptSessionStatus(ScriptSessionState.STOPPED, reason = stopReason)
            throw cancelled
        } catch (failure: Exception) {
            mutableStatus.value = ScriptSessionStatus(ScriptSessionState.FAILED, failure)
        } finally {
            synchronized(control) { execution = null }
        }
    }

    /** Requests a pause at the next API checkpoint; returns false outside RUNNING. */
    fun pause(): Boolean = transition(ScriptSessionState.RUNNING, ScriptSessionState.PAUSING)

    /** Requests a fresh screen check before continuing; returns false outside PAUSED. */
    fun resume(): Boolean = transition(ScriptSessionState.PAUSED, ScriptSessionState.REVALIDATING)

    /** Cancels waits, host calls and busy JS. Example: `session.stop()` from an overlay. */
    fun stop(reason: String = "Interrompido pelo usuário"): Boolean = synchronized(control) {
        val job = execution ?: return false
        if (mutableStatus.value.state in terminalStates) return false
        stopReason = reason
        mutableStatus.value = ScriptSessionStatus(ScriptSessionState.STOPPING)
        job.cancel()
        true
    }

    private suspend fun checkpoint(host: SessionAutomationHost) {
        while (true) {
            currentCoroutineContext().ensureActive()
            when (status.value.state) {
                ScriptSessionState.RUNNING -> return
                ScriptSessionState.PAUSING -> {
                    host.pauseOperationClock()
                    host.releasePointers()
                    host.invalidateObservations()
                    transition(ScriptSessionState.PAUSING, ScriptSessionState.PAUSED)
                }
                ScriptSessionState.PAUSED -> status.first { it.state != ScriptSessionState.PAUSED }
                ScriptSessionState.REVALIDATING -> {
                    check(host.revalidate()) { "Screen revalidation failed; execution cannot resume" }
                    host.resumeOperationClock()
                    transition(ScriptSessionState.REVALIDATING, ScriptSessionState.RUNNING)
                }
                else -> throw CancellationException("Script session is stopping")
            }
        }
    }

    private fun transition(from: ScriptSessionState, to: ScriptSessionState): Boolean = synchronized(control) {
        if (mutableStatus.value.state != from) return false
        mutableStatus.value = ScriptSessionStatus(to)
        true
    }

    private companion object {
        val terminalStates = setOf(ScriptSessionState.STOPPED, ScriptSessionState.COMPLETED, ScriptSessionState.FAILED)
    }
}

package com.buzbuz.smartautoclicker.core.script.runtime.session

import java.util.concurrent.atomic.AtomicBoolean
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.NonCancellable
import kotlinx.coroutines.coroutineScope
import kotlinx.coroutines.currentCoroutineContext
import kotlinx.coroutines.ensureActive
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlinx.coroutines.withContext

/** Owns the shared capture/detector/gesture lifetime. Both execution modes must use one instance. */
class AutomationSessionCoordinator(
    private val resourceDispatcher: CoroutineDispatcher,
    private val releaseResources: suspend () -> Unit,
) {
    private val ownership = Mutex()

    /** Rejects concurrent sessions and releases resources even on cancellation.
     * Example: `coordinator.withSession { access -> access.perform { observe() } }`.
     */
    suspend fun <T> withSession(block: suspend (AutomationSessionAccess) -> T): T {
        check(ownership.tryLock()) { "An automation session already owns the screen resources" }
        val access = AutomationSessionAccess(resourceDispatcher)
        try {
            return coroutineScope { block(access) }
        } finally {
            try {
                withContext(NonCancellable + resourceDispatcher) {
                    access.close()
                    releaseResources()
                }
            } finally {
                ownership.unlock()
            }
        }
    }
}

/** Session-scoped access rejects callbacks retained by a completed session. */
class AutomationSessionAccess internal constructor(private val dispatcher: CoroutineDispatcher) {
    private val active = AtomicBoolean(true)
    private val operations = Mutex()

    /** Serializes screen operations on the detector's dispatcher and rejects late results.
     * Example: `access.perform { detector.detectImage(...) }`.
     */
    suspend fun <T> perform(operation: suspend () -> T): T = operations.withLock {
        check(active.get()) { "The automation session has ended" }
        withContext(dispatcher) {
            currentCoroutineContext().ensureActive()
            check(active.get()) { "The automation session has ended" }
            val result = operation()
            currentCoroutineContext().ensureActive()
            check(active.get()) { "The automation session has ended" }
            result
        }
    }

    internal suspend fun close() {
        active.set(false)
        // A retained callback may already be inside a non-interruptible native detection.
        // Wait for it before releasing the detector and allowing another session to start.
        operations.withLock { }
    }
}

